"""Keep the statistics art names on the shared navigation silhouette family."""
from pathlib import Path

root = Path(__file__).resolve().parents[2]
icons = {'book': 'BookOpen', 'calendar': 'Calendar', 'clock': 'Clock',
         'closedBook': 'Library', 'flame': 'Flame', 'openBook': 'BookOpen',
         'page': 'Note', 'sessions': 'Sessions', 'sparkBook': 'Goal',
         'speed': 'Gauge', 'trophy': 'Trophy'}
lines = ['#pragma once', '#include "NavigationIcons.h"', '#include "ToyboxScreen.h"', '',
         '// Generated by tools_local/statistics_art/generate.py.', '// clang-format off', 'namespace statsart {']
for name, source in icons.items():
    lines.append(f'inline constexpr freeink::ui::BitmapRef {name}{{navicons::{source}64Bits, 64, 64, freeink::ui::BitmapFormat::Mask1, false}};')
lines.extend(['inline void draw(toybox::Screen& s, freeink::ui::Rect r, const freeink::ui::BitmapRef& art) {',
              '  s.target().bitmap(r, art, freeink::ui::BitmapMode::Contain, freeink::ui::Paint::solid(freeink::ui::Color::Black));',
              '}', '}  // namespace statsart', '// clang-format on'])
(root / 'src/apps_local/ui/StatisticsArt.h').write_text('\n'.join(lines)+'\n', 'utf8')
